from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
WORKER = (ROOT / 'app/src/main/java/vn/kholinhkien/RestoreRecoveryWorker.kt').read_text()
MAIN = (ROOT / 'app/src/main/java/vn/kholinhkien/MainActivity.kt').read_text()
COORD = (ROOT / 'app/src/main/java/vn/kholinhkien/RestoreCloudCoordinator.kt').read_text()
PULL = (ROOT / 'app/src/main/java/vn/kholinhkien/SyncPullWorker.kt').read_text()
DATA = (ROOT / 'app/src/main/java/vn/kholinhkien/Data.kt').read_text()
LIFE = (ROOT / 'app/src/main/java/vn/kholinhkien/RestoreStagingLifecycle.kt').read_text()
checks=[]
def check(label, ok): checks.append((label, bool(ok)))
check('dedicated WorkManager recovery worker exists', 'class RestoreRecoveryWorker' in WORKER)
check('worker requires both owner and exact restore ID inputs', 'KEY_OWNER_ID' in WORKER and 'KEY_RESTORE_ID' in WORKER and 'restoreId' in WORKER)
check('owner ID must be canonical before journal access', 'if (!isCanonicalOwnerId(ownerId) || !isCanonicalRestoreId(restoreId)) return Result.failure()' in WORKER)
check('worker rejects unauthenticated or switched account before DAO access', WORKER.index('currentUserOrNull()?.id != ownerId') < WORKER.index('dao.restoreJournal(ownerId, restoreId)'))
check('journal lookup is scoped to exact owner and restore ID', 'dao.restoreJournal(ownerId, restoreId)' in WORKER and 'journal.ownerId != ownerId' in WORKER)
check('worker never auto-resumes REMOTE_FEED journals', 'journal.sourceType != "LOCAL_ZIP"' in WORKER)
check('interrupted ZIP extraction and failed/aborted sessions remain untouched for explicit recovery', 'setOf("STAGING", "FAILED", "ABORTED")' in WORKER)
check('worker resumes only explicit coordinator-safe journal states', all(x in WORKER for x in ['"STAGED"','"PHOTOS_UPLOADED"','"PAYLOAD_READY"','"CLOUD_STAGING"','"CLOUD_STAGED"','"COMMIT_UNKNOWN"','"COMMIT_CONFIRMED"','"SNAPSHOT_DOWNLOADING"','"SNAPSHOT_DOWNLOADED"']))
check('STAGED state requires durable staging integrity check before resume', 'RestoreStagingLifecycle.canResumeStaged(applicationContext, dao, ownerId, restoreId)' in WORKER)
check('worker uses existing coordinator resume path rather than starting a new restore', 'RestoreCloudCoordinator(applicationContext, dao).resume(ownerId, restoreId)' in WORKER)
check('worker propagates cancellation and preserves journal on retryable failures', 'catch (cancelled: CancellationException)' in WORKER and 'throw cancelled' in WORKER and 'Result.retry()' in WORKER)
check('worker retries incomplete post-commit local cleanup instead of claiming success', 'if (result.localCleanupComplete) Result.success() else Result.retry()' in WORKER)
check('WorkManager request requires connected network', 'setRequiredNetworkType(NetworkType.CONNECTED)' in WORKER)
check('recovery work is unique by owner and restore ID', 'enqueueUniqueWork(' in WORKER and 'inventory-restore-recovery-$ownerId-$restoreId' in WORKER)
check('scheduler reads only current owner journals', 'dao.restoreJournals(ownerId)' in WORKER and 'journal.ownerId != ownerId' in WORKER)
check('scheduler enqueues only resumable local ZIP and COMPLETE cleanup journals', 'journal.sourceType != "LOCAL_ZIP"' in WORKER and 'journal.status != "COMPLETE"' in WORKER)
check('remote feed snapshot recovery remains owned by SyncPullWorker', 'activeRestore.sourceType != "REMOTE_FEED"' in PULL and 'RestoreCloudSnapshotReader' in PULL)
check('coordinator continues to reject pending outbox before remote restore work', 'requireNoPendingOutbox(ownerId)' in COORD)
check('coordinator still serializes resume through shared operation gate', 'suspend fun resume(ownerId: String, restoreId: String): Result = RestoreOperationGate.mutex.withLock' in COORD)
check('snapshot download/apply remains serialized through shared snapshot gate', 'RestoreSnapshotGate.mutex.withLock' in COORD)
check('Room exposes a live owner-scoped restore journal Flow', 'fun observeRestoreJournals(ownerId: String): Flow<List<RestoreJournal>>' in DATA)
check('Compose UI observes journal Flow so worker completion unlocks controls without manual refresh', 'dao.observeRestoreJournals(profile.id)' in MAIN and '.collectAsState(initial = emptyList())' in MAIN)
check('startup schedules safe recovery work for the authenticated profile', 'RestoreRecoveryScheduler.schedulePending(context, dao, profile.id)' in MAIN)
check('normal sign-out cancels only current owner recovery work', 'RestoreRecoveryScheduler.cancelOwner(context, ownerId)' in MAIN)
check('inactive-profile session retirement cancels stale owner recovery work', 'RestoreRecoveryScheduler.cancelOwner(context, restoringOwnerId)' in MAIN)
check('session-recovery sign-out also cancels owner recovery work', MAIN.count('RestoreRecoveryScheduler.cancelOwner(context, ownerId)') >= 2)
check('incomplete staging is not automatically deleted by recovery worker', 'deleteAbortableRestoreJournal' not in WORKER and 'clearRestoreStagedRows' not in WORKER)
check('post-commit cleanup is delegated to coordinator and COMPLETE state remains auditable', 'RestoreCloudCoordinator(applicationContext, dao).resume' in WORKER and 'cleanupCompleted' not in WORKER)
failed=[x for x in checks if not x[1]]
for label,ok in checks: print(('PASS ' if ok else 'FAIL ')+label)
print(f'\n{len(checks)-len(failed)}/{len(checks)} checks PASS')
if failed: raise SystemExit(1)
